import{_ as i,o as t,c as a,a2 as n}from"./chunks/framework.Nk14N-ai.js";const g=JSON.parse('{"title":"Chapter 7: Architecture Walkthrough (kinetic-daemon & kinetic-cli)","description":"","frontmatter":{},"headers":[],"relativePath":"code_walkthrough_daemon.md","filePath":"code_walkthrough_daemon.md"}'),s={name:"code_walkthrough_daemon.md"};function o(r,e,c,l,d,h){return t(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="chapter-7-architecture-walkthrough-kinetic-daemon-kinetic-cli" tabindex="-1">Chapter 7: Architecture Walkthrough (<code>kinetic-daemon</code> &amp; <code>kinetic-cli</code>) <a class="header-anchor" href="#chapter-7-architecture-walkthrough-kinetic-daemon-kinetic-cli" aria-label="Permalink to &quot;Chapter 7: Architecture Walkthrough (`kinetic-daemon` &amp; `kinetic-cli`)&quot;">​</a></h1><p>While <code>kinetic-core</code> defines the strict mathematical laws of the protocol, the <code>kinetic-daemon</code> is the engine that executes them. It orchestrates asynchronous local HTTP REST requests, continuous background storage maintenance, Kademlia DHT gossiping, and DNS interception.</p><p>In this chapter, we explore the high-level decoupled architecture of the Daemon and the user-facing CLI.</p><hr><h2 id="_1-the-asynchronous-orchestrator-kinetic-daemon" tabindex="-1">1. The Asynchronous Orchestrator: <code>kinetic-daemon</code> <a class="header-anchor" href="#_1-the-asynchronous-orchestrator-kinetic-daemon" aria-label="Permalink to &quot;1. The Asynchronous Orchestrator: `kinetic-daemon`&quot;">​</a></h2><p>The daemon is built entirely on the <code>tokio</code> asynchronous runtime. To handle massive concurrent network events while serving instantaneous local DNS queries, the architecture has been rigorously decoupled into distinct operational subsystems.</p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">graph TD</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    UI[Web UI / Browser] --&gt;|HTTP REST| API[API Server&lt;br/&gt;(api.rs)]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    CLI[kinetic-cli] --&gt;|HTTP REST| API</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    </span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    subgraph Daemon Services</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        API --&gt; Storage[(Sled Storage)]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        API --&gt; Network[kinetic-network&lt;br/&gt;Swarm]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        </span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        CA[Certificate Auth&lt;br/&gt;(ca.rs)] --&gt; Proxy[HTTPS Proxy&lt;br/&gt;(proxy.rs)]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        Proxy --&gt; PAC[PAC File Server&lt;br/&gt;(pac.rs)]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        </span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        Nostr[Nostr Client&lt;br/&gt;(nostr.rs)] --&gt;|Delegated VDFs| API</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    end</span></span></code></pre></div><h3 id="_1-1-decoupled-components" tabindex="-1">1.1 Decoupled Components <a class="header-anchor" href="#_1-1-decoupled-components" aria-label="Permalink to &quot;1.1 Decoupled Components&quot;">​</a></h3><ul><li><strong><code>api.rs</code></strong>: The core REST API router that serves the React frontend and handles local control commands from the CLI (e.g., identity generation, name registration, service manifests).</li><li><strong><code>proxy.rs</code> &amp; <code>ca.rs</code></strong>: The proxy engine acts as an HTTP/HTTPS forwarder. It dynamically provisions self-signed TLS certificates on the fly using <code>ca.rs</code>, enabling seamless secure connections to <code>.kin</code> domains without browser warnings.</li><li><strong><code>pac.rs</code></strong>: Serves the Proxy Auto-Configuration (PAC) file required by the OS to route <code>.kin</code> traffic gracefully into the Kinetic loopback interface.</li><li><strong><code>nostr.rs</code></strong>: An encrypted communication layer (NIP-04) allowing mobile devices to delegate intense VDF computations to the desktop daemon.</li></ul><h3 id="_1-2-extensive-test-coverage" tabindex="-1">1.2 Extensive Test Coverage <a class="header-anchor" href="#_1-2-extensive-test-coverage" aria-label="Permalink to &quot;1.2 Extensive Test Coverage&quot;">​</a></h3><p>The Daemon&#39;s modularity allows for extremely rigorous, isolated testing. Instead of testing the entire daemon monolithically, each module is backed by comprehensive inline test suites:</p><ul><li><code>api_tests.rs</code>: Validates REST endpoints, JSON schemas, and state persistence.</li><li><code>proxy_tests.rs</code>: Tests HTTP forwarding, TLS termination, and error fallbacks.</li><li><code>ca_tests.rs</code>: Ensures deterministic generation and validation of the local root CA and leaf certificates.</li></ul><hr><h2 id="_2-the-user-interface-kinetic-cli" tabindex="-1">2. The User Interface: <code>kinetic-cli</code> <a class="header-anchor" href="#_2-the-user-interface-kinetic-cli" aria-label="Permalink to &quot;2. The User Interface: `kinetic-cli`&quot;">​</a></h2><p>While the Web UI is user-friendly, the <code>kinetic-cli</code> is the powerful command-line execution tool designed to interface directly with the daemon&#39;s REST API and orchestrate complex local workflows.</p><p>The CLI architecture employs a deeply modular, subcommand-driven structure:</p><h3 id="_2-1-identity-management-kinetic-cli-identity" tabindex="-1">2.1 Identity Management (<code>kinetic-cli identity</code>) <a class="header-anchor" href="#_2-1-identity-management-kinetic-cli-identity" aria-label="Permalink to &quot;2.1 Identity Management (`kinetic-cli identity`)&quot;">​</a></h3><p>Handles all aspects of the user&#39;s cryptographic Kinetic Identity Document (KID):</p><ul><li><strong><code>create</code></strong>: Generates a new Ed25519 identity keypair and persists it securely to the local vault.</li><li><strong><code>show</code></strong>: Displays the active KID, public key, and signature algorithms.</li><li><strong><code>export</code> / <code>import</code></strong>: Securely backs up and restores the identity keystore.</li></ul><h3 id="_2-2-name-registration-workflow-kinetic-cli-name" tabindex="-1">2.2 Name Registration Workflow (<code>kinetic-cli name</code>) <a class="header-anchor" href="#_2-2-name-registration-workflow-kinetic-cli-name" aria-label="Permalink to &quot;2.2 Name Registration Workflow (`kinetic-cli name`)&quot;">​</a></h3><p>This is the core execution path that initiates the Two-Phase Commit/Reveal protocol for claiming <code>.kin</code> domains.</p><ol><li><p><strong>Phase 1: The Commit &amp; Grind (<code>kinetic-cli name register apple.kin</code>)</strong></p><ul><li>Grabs the latest Drand beacon.</li><li>Broadcasts the Phase 1 Hash Commitment to the DHT.</li><li>Aggressively utilizes local CPU cores to grind the Chia VDF Proof-of-Time.</li><li>Generates a template <code>.reveal.json</code> file in <code>~/.config/kinetic/zones/</code>.</li></ul></li><li><p><strong>Phase 2: Configuration &amp; Reveal (<code>kinetic-cli name publish apple.kin</code>)</strong></p><ul><li>Once the template is configured with the target IP or service manifest, the user runs this command.</li><li>It calculates the Ed25519 signature over the exact payload.</li><li>Submits the finalized cryptographic tuple to the daemon&#39;s API, injecting the payload into the global Kademlia DHT.</li></ul></li></ol><h3 id="_2-3-service-manifests-kinetic-cli-service" tabindex="-1">2.3 Service Manifests (<code>kinetic-cli service</code>) <a class="header-anchor" href="#_2-3-service-manifests-kinetic-cli-service" aria-label="Permalink to &quot;2.3 Service Manifests (`kinetic-cli service`)&quot;">​</a></h3><p>For advanced users operating decentralized web hosts or edge nodes:</p><ul><li><strong><code>init</code></strong>: Bootstraps a service manifest template (configuring HTTPS ports, CDN paths, and failover endpoints).</li><li><strong><code>sign</code></strong>: Cryptographically binds the service manifest to the user&#39;s root KID, preventing spoofing by malicious nodes.</li></ul>',25)])])}const m=i(s,[["render",o]]);export{g as __pageData,m as default};
